@namespace sv_5dd5730e70564fc29aacc57ff2bcc36b.Components.Pages.Board

<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLower()">@Task.Priority</span>
    <span class="due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="card-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move" @onclick="() => OnMoveLeft.InvokeAsync(Task.Id)">← Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move" @onclick="() => OnMoveRight.InvokeAsync(Task.Id)">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
}

@namespace sv_5dd5730e70564fc29aacc57ff2bcc36b.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="Save">Save</button>
        <button class="btn-cancel" @onclick="() => OnCancel.InvokeAsync()">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public EventCallback<TaskItem> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today;

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        var newTask = new TaskItem(0, title, assignee, priority, dueDate, Status);
        await OnSave.InvokeAsync(newTask);

        title = string.Empty;
        assignee = string.Empty;
        priority = "Medium";
        dueDate = DateTime.Today;
    }
}

@namespace sv_5dd5730e70564fc29aacc57ff2bcc36b.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>
    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm Status="@ColumnName" OnSave="HandleSave" OnCancel="HideForm" />
        }
        else
        {
            <button class="btn-add" @onclick="ShowForm">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskAdded { get; set; }

    private bool showForm;

    private void ShowForm() => showForm = true;
    private void HideForm() => showForm = false;

    private async Task HandleSave(TaskItem task)
    {
        await OnTaskAdded.InvokeAsync(task);
        showForm = false;
    }
}

@namespace sv_5dd5730e70564fc29aacc57ff2bcc36b.Components.Pages.Board

<div class="board-stats">
    <span class="stat">Total: @Tasks.Count</span>
    <span class="stat">To Do: @Tasks.Count(t => t.Status == "To Do")</span>
    <span class="stat">In Progress: @Tasks.Count(t => t.Status == "In Progress")</span>
    <span class="stat">Done: @Tasks.Count(t => t.Status == "Done")</span>
    <span class="stat stat-overdue">Overdue: @Tasks.Count(t => t.DueDate < DateTime.Today)</span>
</div>

@code {
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
}

@namespace sv_5dd5730e70564fc29aacc57ff2bcc36b.Components.Pages.Board

<div class="board-search">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchTerm"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> SearchTermChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTermChanged.InvokeAsync(value);
    }
}

@page "/board"
@namespace sv_5dd5730e70564fc29aacc57ff2bcc36b.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStats Tasks="allTasks" />
    <BoardSearchBar SearchTerm="@searchTerm" SearchTermChanged="OnSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="GetTasksForColumn(\"To Do\")"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      OnMoveRight="id => MoveTask(id, \"In Progress\")"
                      OnTaskAdded="HandleTaskAdded" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="GetTasksForColumn(\"In Progress\")"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      OnMoveLeft="id => MoveTask(id, \"To Do\")"
                      OnMoveRight="id => MoveTask(id, \"Done\")"
                      OnTaskAdded="HandleTaskAdded" />

        <KanbanColumn ColumnName="Done"
                      Tasks="GetTasksForColumn(\"Done\")"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      OnMoveLeft="id => MoveTask(id, \"In Progress\")"
                      OnTaskAdded="HandleTaskAdded" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchTerm = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetTasksForColumn(string status)
    {
        var filtered = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void OnSearchChanged(string value)
    {
        searchTerm = value;
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            var index = allTasks.IndexOf(task);
            allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleTaskAdded(TaskItem taskData)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(taskData.Title, taskData.Assignee, taskData.Priority, taskData.DueDate);
            allTasks.Add(created);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

