+    border-radius: 3px;
+    cursor: pointer;
+}
+
+.btn-move:hover {
+    background: #e9ecef;
+}
+
+.column-footer {
+    margin-top: 0.75rem;
+}
+
+.btn-add {
+    width: 100%;
+    padding: 0.4rem;
+    border: 1px dashed #adb5bd;
+    background: transparent;
+    border-radius: 4px;
+    cursor: pointer;
+    color: #6c757d;
+}
+
+.btn-add:hover {
+    background: #e9ecef;
+}
+
+.add-task-form {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+    background: #fff;
+    padding: 0.75rem;
+    border-radius: 6px;
+    border: 1px solid #dee2e6;
+}
+
+.add-task-form input,
+.add-task-form select {
+    padding: 0.4rem 0.5rem;
+    border: 1px solid #dee2e6;
+    border-radius: 4px;
+    font-size: 0.85rem;
+}
+
+.form-actions {
+    display: flex;
+    gap: 0.5rem;
+}
+
+.btn-save {
+    padding: 0.35rem 0.75rem;
+    background: #0d6efd;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-cancel {
+    padding: 0.35rem 0.75rem;
+    background: #6c757d;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.loading {
+    text-align: center;
+    color: #6c757d;
+    padding: 2rem;
+}
+
+.error {
+    color: #dc3545;
+    padding: 1rem;
+    background: #f8d7da;
+    border-radius: 4px;
+}
+

